package com.cosmetic.shopbackend.brand;
import com.cosmetic.shopbackend.identity.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/brands")
public class BrandController {
 private final BrandRepository brands; private final SellerAccountRepository sellers;
 public BrandController(BrandRepository b,SellerAccountRepository s){brands=b;sellers=s;}
 public record BrandRequest(@NotBlank String name,String description,String logoUrl){} public record BrandResponse(String id,String sellerAccountId,String name,String description,String logoUrl,String status){}
 @GetMapping public List<BrandResponse> list(@RequestHeader(value="X-User-Role",required=false) String role,@RequestHeader(value="X-User-Id",required=false) String uid){ RequestActor actor=RequestActor.require(uid,role,AccountRole.SELLER,AccountRole.ADMIN); if(actor.role()==AccountRole.ADMIN) return brands.findAll().stream().map(BrandController::view).toList(); return brands.findAllBySeller_Id(actor.userId()).stream().map(BrandController::view).toList(); }
 @PostMapping public ResponseEntity<BrandResponse> create(@RequestHeader(value="X-User-Role",required=false) String role,@RequestHeader(value="X-User-Id",required=false) String uid,@Valid @RequestBody BrandRequest r){ RequestActor actor=RequestActor.require(uid,role,AccountRole.SELLER); Brand b=new Brand();b.setSeller(sellers.findById(actor.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED)));copy(b,r);brands.save(b);return ResponseEntity.status(HttpStatus.CREATED).body(view(b)); }
 @GetMapping("/{id}") public BrandResponse get(@PathVariable String id,@RequestHeader(value="X-User-Role",required=false) String role,@RequestHeader(value="X-User-Id",required=false) String uid){return view(authorized(id,uid,role));}
 @PutMapping("/{id}") public BrandResponse update(@PathVariable String id,@RequestHeader(value="X-User-Role",required=false) String role,@RequestHeader(value="X-User-Id",required=false) String uid,@Valid @RequestBody BrandRequest r){Brand b=authorized(id,uid,role);copy(b,r);return view(brands.save(b));}
 @PatchMapping("/{id}/status") public BrandResponse status(@PathVariable String id,@RequestParam BrandStatus status,@RequestHeader(value="X-User-Role",required=false) String role,@RequestHeader(value="X-User-Id",required=false) String uid){Brand b=authorized(id,uid,role);b.setStatus(status);return view(brands.save(b));}
 private Brand authorized(String id,String uid,String role){RequestActor actor=RequestActor.require(uid,role,AccountRole.SELLER,AccountRole.ADMIN);if(actor.role()==AccountRole.ADMIN)return brands.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return brands.findByIdAndSeller_Id(id,actor.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 private static void copy(Brand b,BrandRequest r){b.setName(r.name());b.setDescription(r.description());b.setLogoUrl(r.logoUrl());} private static BrandResponse view(Brand b){return new BrandResponse(b.getId(),b.getSeller().getId(),b.getName(),b.getDescription(),b.getLogoUrl(),b.getStatus().name());}
}
